export type RefundStatus = (typeof RefundStatus)[keyof typeof RefundStatus];

export const RefundStatus = {
    pending: 'pending',
    succeeded: 'succeeded',
    failed: 'failed'
} as const;

/**
 * Why the money went back. `cancellation` — the order was cancelled after payment, or the unshipped remainder of one fulfillment order was (then `returnId` names that cancellation); `return` — goods came back and were received; `goodwill` — an operator chose to.
 */
export type RefundReason = (typeof RefundReason)[keyof typeof RefundReason];

export const RefundReason = {
    cancellation: 'cancellation',
    goodwill: 'goodwill',
    return: 'return'
} as const;

/**
 * Why the provider last refused a refund, as a closed code. Staff only (`display:Payment`). `unknown` is anything the provider's adapter did not classify; the raw wording stays in the logs.
 */
export type RefundFailureReason = (typeof RefundFailureReason)[keyof typeof RefundFailureReason];

export const RefundFailureReason = {
    declined: 'declined',
    insufficient_funds: 'insufficient_funds',
    expired_or_canceled_card: 'expired_or_canceled_card',
    lost_or_stolen_card: 'lost_or_stolen_card',
    provider_unavailable: 'provider_unavailable',
    unknown: 'unknown'
} as const;

/**
 * One attempt to give money back — a record per attempt, not a field on the payment. The idempotency key is stored but never published. The provider's refund id and a failed refund's `failureReason` go to staff only (`display:Payment`); the provider's own error wording stays in the logs.
 */
export interface Refund {
    id: Id;
    /**
     * The amount returned, in the payment's own `currency`.
     * @minimum 0
     */
    amount: number;
    /** ISO-4217 currency code, copied from the payment. */
    currency: string;
    /** `pending` while the provider is being asked; `failed` when it refused — a sweep retries the same refund with the same idempotency key; `succeeded` once the money is confirmed back (or, for a hand-paid payment, reported back by the operator). */
    status: RefundStatus;
    reason: RefundReason;
    returnId?: Id;
    /** When the refund succeeded. Absent while it has not. */
    settledAt?: string;
    /** The provider's id for the refund (Stripe's `re_…`). Staff only. */
    providerRefundRef?: string;
    failureReason?: RefundFailureReason;
    createdAt: string;
}

/**
 * The label a payment shows, derived from the stored status and its refund records (Shopify's `displayFinancialStatus`). `incomplete` — awaiting confirmation or action; `pending` — processing; `succeeded` — paid, no refund record; `refund_pending` — any refund still pending or failed (wins over the next two); `partially_refunded` — paid with at least one settled refund; `refunded` — fully returned (every unit of `amount`, no refund still open); `failed` — declined; `cancelled` — the order was cancelled before the payment settled.
 */
export type PaymentDisplayStatus = (typeof PaymentDisplayStatus)[keyof typeof PaymentDisplayStatus];

export const PaymentDisplayStatus = {
    incomplete: 'incomplete',
    pending: 'pending',
    succeeded: 'succeeded',
    refund_pending: 'refund_pending',
    partially_refunded: 'partially_refunded',
    refunded: 'refunded',
    failed: 'failed',
    cancelled: 'cancelled'
} as const;

/**
 * What the requesting caller may do to this payment. Money is this module's to answer for; the order's own moves are on `Order.actions`, and a client that needs both composes them rather than deciding either for itself.
 */
export interface PaymentActions {
    /** Whether `POST /payments/{id}/confirm` would be accepted — the payment is awaiting confirmation or retryable after a decline, AND the order can still reach `paid`, AND the caller is the payer and holds `checkout:Cart` (staff reading the payment are never offered it). */
    pay: boolean;
    /** Whether `POST /payments/order/{orderId}/refund` would be accepted. False once nothing is left to refund (fully refunded, or the rest already asked back), which is what greys the control out rather than letting the operator discover it by clicking. */
    refund: boolean;
}

/**
 * The provider-facing lifecycle. A refunded payment, whole or in part, stays `succeeded`: `displayStatus` and `amountRefunded` say how much went back. `cancelled` means the order was cancelled and the provider confirmed the intent closed; money that still arrives on it is settled and returned. `requires_action` means the bank wants a challenge answered in the browser (3-D Secure) and `processing` that the provider has taken the payment but not settled it — both are in flight, and `POST /payments/{id}/sync` is what resolves them without waiting for the webhook. `declined` is retryable: the confirm endpoint accepts the same payment again with another method. Full transition table: docs/modules/payments.md#status-transitions
 */
export type PaymentStatus = (typeof PaymentStatus)[keyof typeof PaymentStatus];

export const PaymentStatus = {
    requires_confirmation: 'requires_confirmation',
    requires_action: 'requires_action',
    processing: 'processing',
    succeeded: 'succeeded',
    declined: 'declined',
    cancelled: 'cancelled'
} as const;

/**
 * How the money moved. `card` for anything that went through the provider port; the other three are set only by `POST /payments/order/{orderId}/offline`, from what the admin chose there.
 */
export type PaymentMethod = (typeof PaymentMethod)[keyof typeof PaymentMethod];

export const PaymentMethod = {
    card: 'card',
    bank_transfer: 'bank_transfer',
    cash: 'cash',
    other: 'other'
} as const;

export interface Payment {
    id: Id;
    orderId: Id;
    userId?: Id;
    /**
     * The order's total as the intent froze it. Always two decimal places, rounded half-up at the point of calculation. If the provider reports a success for a different amount or currency, the payment reads `succeeded` with what ARRIVED here, its order is cancelled and the money is returned.
     * @minimum 0
     */
    amount: number;
    /** ISO-4217 currency code (e.g. EUR) */
    currency: string;
    /**
     * How much of `amount` has been asked back, pending and succeeded together — the same reading as Stripe's `amount_refunded`. Counted when a refund is opened, so two racing partial refunds cannot return more than was paid.
     * @minimum 0
     */
    amountRefunded: number;
    /** One record per refund attempt, oldest first. */
    refunds: Refund[];
    /** The provider-facing lifecycle. A refunded payment, whole or in part, stays `succeeded`: `displayStatus` and `amountRefunded` say how much went back. `cancelled` means the order was cancelled and the provider confirmed the intent closed; money that still arrives on it is settled and returned. `requires_action` means the bank wants a challenge answered in the browser (3-D Secure) and `processing` that the provider has taken the payment but not settled it — both are in flight, and `POST /payments/{id}/sync` is what resolves them without waiting for the webhook. `declined` is retryable: the confirm endpoint accepts the same payment again with another method. Full transition table: docs/modules/payments.md#status-transitions */
    status: PaymentStatus;
    displayStatus: PaymentDisplayStatus;
    /** The provider's own id for the payment intent (Stripe's `pi_…`). Sent only to a caller holding `display:Payment`, so support can look the payment up at the provider; never to the payer. Absent on a `manual` payment. */
    providerRef?: string;
    /** The order's number. Present on `GET /payments` rows only. */
    orderNumber?: string;
    /** The order's customer email. Present on `GET /payments` rows only. */
    email?: string;
    /** Which provider implementation handled it — the name the deployment registered (`NODE_PAYMENT_PROVIDER`), or `manual` for a payment recorded by hand (`POST /payments/order/{orderId}/offline`). */
    provider: string;
    /** How the money moved. `card` for anything that went through the provider port; the other three are set only by `POST /payments/order/{orderId}/offline`, from what the admin chose there. */
    method: PaymentMethod;
    /**
     * Free text identifying an offline payment — a bank transaction id, a receipt number. Set only by `POST /payments/order/{orderId}/offline`; absent from a card payment.
     * @maxLength 120
     */
    reference?: string;
    /** When the money actually arrived, as the admin recording it reported — possibly earlier than `createdAt`. Set only by `POST /payments/order/{orderId}/offline`; absent from a card payment. */
    receivedAt?: string;
    /** `true` once a refunded `manual` payment has had its money returned to the customer outside this application — there is no provider to ask, so this is the admin's own record that it was done. Absent otherwise. */
    refundedByHand?: boolean;
    /** Returned by `POST /payments/intent` alone, never stored and never read back: it authorises completing this payment against the provider from the browser. Absent from every other response. */
    clientSecret?: string;
    /** The only card digits a payment system may remember. Survives a refund — refunding does not clear it. */
    cardLast4?: string;
    actions?: PaymentActions;
    createdAt?: string;
    updatedAt?: string;
}

export interface PaymentEnvelope {
    success: EnvelopeSuccess;
    status: EnvelopeStatus;
    message: EnvelopeMessage;
    data: Payment;
}

export interface OrderByReferenceResponseEnvelope {
    success: EnvelopeSuccess;
    status: EnvelopeStatus;
    message: EnvelopeMessage;
    data: Order;
}

export interface RefundPaymentRequest {
    /**
     * How much to return, a decimal in the payment's own currency. Absent means everything still refundable.
     * @exclusiveMinimum 0
     */
    amount?: number;
    /**
     * ISO-4217 code of `amount`. Optional; when sent it must equal the payment's own currency, so an amount written in another unit is refused instead of being read as this one.
     * @maxLength 3
     */
    currency?: string;
}

/**
 * How the money arrived. `card` is not offered here — that path is `POST /payments/intent`.
 */
export type RecordOfflinePaymentRequestMethod =
    (typeof RecordOfflinePaymentRequestMethod)[keyof typeof RecordOfflinePaymentRequestMethod];

export const RecordOfflinePaymentRequestMethod = {
    bank_transfer: 'bank_transfer',
    cash: 'cash',
    other: 'other'
} as const;

export interface RecordOfflinePaymentRequest {
    /** How the money arrived. `card` is not offered here — that path is `POST /payments/intent`. */
    method: RecordOfflinePaymentRequestMethod;
    /**
     * A bank transaction id, a receipt number — whatever ties this record to the money.
     * @minLength 1
     * @maxLength 120
     */
    reference?: string;
    /** When the money arrived. Must not be in the future. Defaults to now. */
    receivedAt?: string;
}

export interface ConfirmPaymentRequest {
    /**
     * The provider's opaque handle for the payment method, produced in the BROWSER by the provider's own widget. Never a card number — a card number reaching this API would put the whole deployment in the heavyweight PCI bracket, which is the reason this field is shaped the way it is.
     * @minLength 3
     * @maxLength 255
     * @pattern ^[\w-]+$
     */
    paymentMethodRef: string;
}

/**
 * One delivery, in this module's normalised shape: which event it is and which intent it names, and nothing about what happened. A real provider sends its OWN event shape and its implementation of the provider port translates it into this. The outcome is never read from the body: once the delivery is authenticated, the server asks the provider for the payment's state, because providers do not guarantee the order events arrive in.
 */
export interface PaymentWebhookEvent {
    /**
     * The provider's event id. Deduplicated, so a retry settles nothing twice.
     * @maxLength 200
     */
    id: string;
    /**
     * Which intent the event is about. Absent for an event this API ignores.
     * @maxLength 200
     */
    providerRef?: string;
}

export interface ShippingMethod {
    /** Stable id, frozen onto orders at checkout (standard, express, pickup). */
    id: string;
    /**
     * Flat rate, in `currency`.
     * @minimum 0
     */
    price: number;
    /** ISO-4217 currency code (e.g. EUR) — this deployment's `NODE_DEFAULT_CURRENCY`. */
    currency: string;
    /**
     * Items total at which this method becomes free. Absent — it never does.
     * @minimum 0
     */
    freeAbove?: number;
    /** Whether a parcel sent by this method carries a tracking code. Looked up live by the order's shippingMethod id when it ships — not frozen at checkout — so a rate change also changes what the shipping door requires. */
    tracked: boolean;
    /** Whether this method needs a shipping address to deliver to (a courier does; a counter pickup does not). Checkout enforces it — a basket needing shipping refuses with `CART_ADDRESS_REQUIRED` when the chosen method requires one and none is on file. */
    requiresAddress: boolean;
    /**
     * Grams. Absent means no floor. Enforced server-side — `PUT /cart/shipping-method` refuses a basket that doesn't reach it, and checkout refuses one chosen outside its range.
     * @minimum 0
     */
    minWeight?: number;
    /**
     * Grams. Absent means no ceiling. Enforced the same way as minWeight.
     * @minimum 0
     */
    maxWeight?: number;
}

