/**
 * Success
 */
export type SuccessResponse = MessageResponse;

/**
 * The request could not be understood or authenticated as what it claims to be — distinct from `ValidationError`, which is a well-formed request whose FIELDS are wrong. Used where a caller is a machine rather than a form: an unverifiable webhook signature is the case that needs it.
 */
export type BadRequestResponse = ErrorResponse;

/**
 * Unauthorized
 */
export type UnauthorizedResponse = ErrorResponse;

/**
 * Forbidden
 */
export type ForbiddenResponse = ErrorResponse;

/**
 * Resource not found
 */
export type NotFoundResponse = ErrorResponse;

/**
 * The request conflicts with the current state of the resource
 */
export type ConflictResponse = ErrorResponse;

/**
 * The request's `If-Match` no longer matches the stored resource: it was changed (or removed) after the caller read it. Nothing was written. Read it again, reapply the edit, and resend with the new `ETag`.
 */
export type PreconditionFailedResponse = ErrorResponse;

/**
 * The request body is larger than this deployment accepts (`NODE_JSON_BODY_LIMIT`, 100kb by default; multipart uploads are bounded separately by `NODE_MAX_UPLOAD_BYTES`). Refused by the body parser before any route runs, which is why it is declared for every body-accepting operation rather than by hand.
 */
export type PayloadTooLargeResponse = ErrorResponse;

/**
 * The request body declares a character set or a content encoding the body parser cannot read. Refused before any route runs, like `413` above — a body whose content-type simply matches no parser is NOT this: it reaches the route, which answers whatever it says about a request missing every field.
 */
export type UnsupportedMediaTypeResponse = ErrorResponse;

/**
 * The caller has spent a rate-limit budget and must wait. The wait is in the standard `RateLimit`/`Retry-After` headers, and — where the endpoint has a budget of its own to report, like a resend cooldown — in the error `details` too.
 */
export type TooManyRequestsResponse = ErrorResponse;

/**
 * A dependency the request needed (Mongo, Redis) is unreachable right now — the SERVER is temporarily unable, not the request refused (RFC 9110 §15.6.4). Every route can answer this: `getAuth` for any bearer request, or a controller's own database call. The `Retry-After` header carries a rough wait hint, a few seconds, not a promise — there is no queue depth or circuit-breaker state to compute a real one from.
 */
export type ServiceUnavailableResponse = ErrorResponse;

/**
 * Internal server error
 */
export type InternalErrorResponse = ErrorResponse;

export type PageParamParameter = Page;

export type PageSizeParamParameter = PageSize;

export type TextParamParameter = Text;

/**
 * The token the active human-challenge provider issued to the client — see `GET /antibot/config`. Absent when that provider is `none`.
 */
export type AntibotChallengeTokenHeaderParameter = string;

/**
 * An opaque, client-generated value (a UUID by convention) that makes a retried write safe, and that this route REQUIRES: a request without it answers 400 (`IDEMPOTENCY_KEY_REQUIRED`) and nothing is written. Repeating the request with the SAME key and the SAME body replays the first response (`Idempotent-Replay: true`, no repeated write); the same key with a DIFFERENT body answers 422; a key still being processed by another in-flight request answers 409.
 */
export type RequiredIdempotencyKeyHeaderParameter = string;

/**
 * An opaque, client-generated value (a UUID by convention) that makes a retried write safe. Repeating this request with the SAME key and the SAME body replays the first response (`Idempotent-Replay: true`, no repeated write) instead of running it again; the same key with a DIFFERENT body answers 422; a key still being processed by another in-flight request answers 409. Omitting the header simply forgoes replay protection — the write still happens normally.
 */
export type IdempotencyKeyHeaderParameter = string;

/**
 * The `ETag` this client last read for the resource (RFC 9110 §13.1.1), quoted as received. The write runs only if the stored resource is still at that version; otherwise it answers 412 `PRECONDITION_FAILED` and changes nothing. `*` means "any version, as long as it exists". Omitting the header keeps the old behaviour: the write is unconditional, last writer wins.
 */
export type IfMatchHeaderParameter = string;

